<?php declare(strict_types=1); ?><!doctype html><html lang="<?= e($locale) ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e(villa_ui('Çeviri yönetimi')) ?></title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:1050px;margin:35px auto;padding:0 18px}.panel{background:white;padding:22px;border-radius:14px;margin:15px 0}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #edf0ed}input,textarea,select{width:100%;box-sizing:border-box;padding:10px;border:1px solid #dfe6e0;border-radius:8px;font:inherit}textarea{min-height:50px}button{background:#176b50;color:white;border:0;padding:11px 16px;border-radius:8px;font-weight:700}.key{font-family:monospace;font-size:12px;color:#68756c}
