?= e($language['code']) ?>" <?= $language['code']===$locale?'selected':'' ?>><?= e($language['name']) ?> (<?= e($language['code']) ?>)</option><?php endforeach; ?></select></form><form method="post" action="/admin/translations"><?= csrf_field() ?><input type="hidden" name="lang" value="<?= e($locale) ?>"><section class="panel"><table><thead><tr><th><?= e(villa_ui('Çeviri anahtarı')) ?></th><th><?= e(villa_ui('Metin')) ?></th></tr></thead><tbody><?php foreach($translations as $key=>$value): ?><tr><td class="key"><?= e($key) ?></td><td><textarea name="translations[<?= e($key) ?>]"><?= e($value) ?></textarea></td></tr><?php endforeach; ?></tbody></table><p><button type="submit"><?= e(villa_ui('Çevirileri kaydet')) ?></button></p></section></form><form method="post" action="/admin/translations"><?= csrf_field() ?><input type="hidden" name="lang" value="<?= e($locale) ?>"><section class="panel"><h2><?= e(villa_ui('Yeni çeviri anahtarı')) ?></h2><input name="new_key" placeholder="translation.key" required><textarea name="new_value" placeholder="Çeviri metni" required></textarea><p><button type="submit"><?= e(villa_ui('Yeni anahtar ekle')) ?></button></p></section></form></main></body></html>